import { styled, View } from '@tamagui/web';
import type { ReactNode } from 'react';

import { ariaAndDataAttributes } from '../../helpers/ariaAndDataAttributes';
import { cx } from '../../helpers/composeClassNames';
import { pickWebPressHandlers } from '../../helpers/pickAttributes';
import type { UlActionAttributes } from '../../types/ElementAttributes';

export type ListboxProps = {
	/** Referenced by the combobox's `aria-controls`. */
	id: string;
	children?: ReactNode;
} & Omit<UlActionAttributes, 'id' | 'role'>;

// generated by scripts/generate-frame-values.mts from @rocket.chat/fuselage-tokens, do not edit

const listboxFrame = {
	display: 'block',
	flexDirection: 'row',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	render: 'ul',
	margin: 0,
	padding: 0,
} as const;

// end of generated

// Declared where it renders: zero-runtime only erases a `styled()` whose every use is in its own module
const ListboxFrame = styled(View, { ...listboxFrame });

/**
 * A popup list of `ListboxOption`s that a combobox controls: focus stays on the combobox, which marks the active option with `aria-activedescendant`.
 */
function Listbox(props: ListboxProps) {
	return (
		<ListboxFrame
			className={cx('rcx-box rcx-box--full rcx-listbox', props.className)}
			render={
				<ul
					{...ariaAndDataAttributes(props)}
					{...pickWebPressHandlers(props)}
					ref={props.ref}
					id={props.id}
					title={props.title}
					role='listbox'
					tabIndex={props.tabIndex}
				/>
			}
		>
			{props.children}
		</ListboxFrame>
	);
}

export default Listbox;
